(() => {
'use strict';
const salons=window.ULTIMA_SALONS,categories=window.ULTIMA_CATEGORIES,services=window.ULTIMA_SERVICES;
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="1"/><path d="M16 3v4M8 3v4M3 11h18m-12 4h2m4 0h2m-8 3h2"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>','arrow-up':'<path d="M5 19 19 5M5 5h14v14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',grid:'<rect x="3" y="3" width="6" height="6"/><rect x="15" y="3" width="6" height="6"/><rect x="3" y="15" width="6" height="6"/><rect x="15" y="15" width="6" height="6"/>',scissors:'<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="m8 8 13 13M8 16 21 3m-8 9 2-2"/>',sparkle:'<path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6L12 2Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',leaf:'<path d="M20 3S9 1 5 7s0 12 5 12S21 15 20 3Z"/><path d="M3 22 15 9"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',check:'<path d="m4 12 5 5L20 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
icons.sliders='<path d="M4 7h6m4 0h6M4 17h11m4 0h1"/><circle cx="12" cy="7" r="2"/><circle cx="17" cy="17" r="2"/>';icons.chevron='<path d="m9 5 7 7-7 7"/>';
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.sparkle}</svg>`;
function hydrate(r=document){$$('[data-icon]',r).forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function read(key,fallback){try{return JSON.parse(localStorage.getItem('ultima.'+key))??fallback;}catch{return fallback;}}
function persist(key,value){try{localStorage.setItem('ultima.'+key,JSON.stringify(value));return true;}catch{toast('Браузер не разрешает сохранение. Данные доступны до закрытия страницы.');return false;}}
let favorites=new Set((Array.isArray(read('favorites',[]))?read('favorites',[]):[]).filter(id=>salons.some(s=>s.id===id)));
let plans=read('plans',[]);if(!Array.isArray(plans))plans=[];plans=plans.filter(p=>p&&salons.some(s=>s.id===p.salon)&&Array.isArray(p.services));
const state={category:'all',district:'all',query:'',sort:'editorial',favorites:false,limit:6};
let returnNav='catalog';
function setNav(name){if(name!=='plans'&&name!=='account')returnNav=name;$$('[data-nav]').forEach(e=>{const selected=e.dataset.nav===name;e.classList.toggle('active',selected);if(selected)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});}

const dialog=$('#main-dialog');let activeSalon=null,detailTab='overview',toastTimer;
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const categoryName=id=>categories.find(c=>c.id===id)?.name||id;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function counts(){$('#favorite-count').textContent=favorites.size;$('#plan-count').textContent=account?.stats.visits||plans.filter(p=>p.status==='completed').length;}
function imageMarkup(s,hero=false){return s.image?`<img src="./assets/${s.image}.webp" alt="${esc(s.imageNote||s.brand)}" ${hero?'':'loading="lazy"'}>`:`<div class="placeholder"><span class="brand-placeholder">${esc(s.brand)}<small style="display:block;font:8px var(--sans);letter-spacing:2px;margin-top:14px">ДОСЬЕ ФИЛИАЛА</small></span></div>`;}
function filtered(filters=state){let list=salons.filter(s=>(filters.category==='all'||s.categories.includes(filters.category))&&(filters.district==='all'||s.district===filters.district)&&(!filters.favorites||favorites.has(s.id)));
 const q=filters.query.toLocaleLowerCase('ru').trim();if(q)list=list.filter(s=>[s.brand,s.branch,s.address,s.district,...s.services.map(k=>services[k]?.name||'')].join(' ').toLocaleLowerCase('ru').includes(q));
 if(filters.sort==='rating')list.sort((a,b)=>(ratings[b.id]?.average||0)-(ratings[a.id]?.average||0)||(ratings[b.id]?.count||0)-(ratings[a.id]?.count||0));if(filters.sort==='name')list.sort((a,b)=>a.brand.localeCompare(b.brand,'ru'));if(filters.sort==='priced')list.sort((a,b)=>(b.price?1:0)-(a.price?1:0));return list;}
function card(s){const tags=s.categories.filter(c=>c!=='parallel').slice(0,3);return `<article class="salon-card" data-salon-card="${s.id}"><div class="card-media"><div class="card-image" role="button" tabindex="0" data-open="${s.id}" aria-label="Подробнее: ${esc(s.brand+' · '+s.branch)}">${imageMarkup(s)}</div><span class="card-district">${icon('pin')}${esc(s.district)}</span><button class="heart-button ${favorites.has(s.id)?'active':''}" data-favorite="${s.id}" aria-label="${favorites.has(s.id)?'Удалить из избранного':'Добавить в избранное'}: ${esc(s.brand)}" aria-pressed="${favorites.has(s.id)}">${icon('heart')}</button></div><div class="card-content"><div class="card-heading"><button class="card-title-button" data-open="${s.id}"><h3>${esc(s.brand)}</h3></button></div><p class="card-branch">${esc(s.branch)}</p><button class="card-rating" data-salon-reviews="${s.id}">${ratingMarkup(s)}</button><div class="card-tags">${tags.map(c=>`<span>${esc(categoryName(c))}</span>`).join('')}</div><div class="card-bottom"><span class="card-price">${s.price?`${esc(s.priceLabel)} <b>от ${money(s.price)}</b>`:s.pending?'Сведения уточняются':'Стоимость по прайсу салона'}</span><button class="card-open" data-open="${s.id}">Подробнее ${icon('chevron')}</button></div>${s.pending?'<p class="card-status">Данные филиала уточняются</p>':''}</div></article>`;}
function render(){const list=filtered();$('#salon-grid').innerHTML=list.length?list.slice(0,state.limit).map(card).join(''):`<div class="empty-state"><h3>${state.favorites?'Нет сохранённых салонов':'Ничего не найдено'}</h3><p>${state.favorites?'Нажмите на сердечко в карточке понравившегося салона.':'Попробуйте другой район, направление или название.'}</p><button class="button outline" data-reset>Показать все салоны ${icon('arrow')}</button></div>`;$('#result-count').textContent=`${list.length} ${noun(list.length,['адрес','адреса','адресов'])} · ${state.favorites?'ваше избранное':'коллекция Ultima'}`;$('#load-more').hidden=state.limit>=list.length;$('#favorites-filter').classList.toggle('active',state.favorites);$('#favorites-filter').setAttribute('aria-pressed',state.favorites);$('#district').value=state.district;$('#sort').value=state.sort;$('#search').value=state.query;updateMobileFilters();$$('.category').forEach(e=>{e.classList.toggle('active',e.dataset.category===state.category);e.setAttribute('aria-pressed',e.dataset.category===state.category);});const chips=[];if(state.district!=='all')chips.push(`<button class="filter-chip" data-clear="district">${esc(state.district)} ${icon('close')}</button>`);if(state.category!=='all')chips.push(`<button class="filter-chip" data-clear="category">${esc(categoryName(state.category))} ${icon('close')}</button>`);if(state.query)chips.push(`<button class="filter-chip" data-clear="query">${esc(state.query)} ${icon('close')}</button>`);if(chips.length)chips.push('<button class="text-button" data-reset>Сбросить всё</button>');$('#active-filters').innerHTML=chips.join('');counts();}
function noun(n,forms){return forms[n%10===1&&n%100!==11?0:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?1:2];}
function reset(){Object.assign(state,{category:'all',district:'all',query:'',favorites:false,sort:'editorial',limit:6});render();}
async function favorite(id){const was=favorites.has(id);if(account){try{await api('favorites/'+id,was?'DELETE':'POST',was?undefined:{});}catch(e){toast(e.message);return;}}if(was)favorites.delete(id);else favorites.add(id);if(!account)persist('favorites',[...favorites]);render();if(activeSalon===id&&dialog.open)showSalon(id,detailTab);toast(was?'Место удалено из избранного':account?'Салон сохранён в профиле':'Сохранено на устройстве. Войдите для синхронизации.');}
function open(html){dialog.classList.toggle('filter-mode',html.includes('id="mobile-filter-form"'));$('#dialog-content').innerHTML=html;hydrate(dialog);if(!dialog.open)dialog.showModal();dialog.scrollTop=0;requestAnimationFrame(()=>{$('#dialog-title',dialog)?.setAttribute('tabindex','-1');$('#dialog-title',dialog)?.focus({preventScroll:true});});}
function close(){dialog.close();}
dialog.addEventListener('close',()=>{$('#mobile-filters').setAttribute('aria-expanded','false');setNav(returnNav);activeSalon=null;if(location.hash.startsWith('#salon/'))history.replaceState(null,'',location.pathname+location.search+'#collection');});
$('.close-dialog').addEventListener('click',close);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
function showSalon(id,tab='overview'){const s=salons.find(s=>s.id===id);if(!s)return;activeSalon=id;detailTab=tab;history.replaceState(null,'',location.pathname+location.search+'#salon/'+id);open(`<div class="dialog-hero">${imageMarkup(s,true)}<span class="image-caption">${esc(s.imageNote||'Досье бренда · фотография не представлена')}</span></div><div class="dialog-main"><div class="eyebrow">${esc(s.district)} / КАРТОЧКА ФИЛИАЛА</div><h2 id="dialog-title">${esc(s.brand)}</h2><p class="dialog-subtitle">${esc(s.branch)}<br>${esc(s.address)}</p><div class="dialog-actions">${s.booking?`<button class="button dark" data-plan="${id}">Спланировать визит ${icon('arrow')}</button>`:`<a class="button outline" href="${esc(s.source)}" target="_blank" rel="noopener noreferrer">Источник сведений ${icon('arrow-up')}</a>`}<button class="button outline" data-favorite="${id}">${icon('heart')} ${favorites.has(id)?'В избранном':'Сохранить место'}</button></div><div class="detail-tabs" role="tablist" aria-label="Информация о салоне">${[['overview','Обзор'],['services','Услуги'],['contacts','Адрес']].map(([k,n])=>`<button class="${k===tab?'active':''}" role="tab" aria-selected="${k===tab}" data-tab="${k}">${n}</button>`).join('')}</div><div class="detail-rating"><button data-salon-reviews="${s.id}">${ratingMarkup(s)} ${icon('chevron')}</button><small>Оценки пользователей</small></div><div class="detail-body">${detailContent(s,tab)}</div></div>`);}
function detailContent(s,tab){if(tab==='services')return `<p>Избранные направления меню. Состав процедуры и итоговую стоимость подтверждает салон.</p>${s.services.map(k=>{const p=s.prices?.[k];return `<div class="service-row"><div><h4>${esc(services[k].name)}</h4><small>${esc(p?.note||'Состав и стоимость уточняются в филиале.')}</small></div><div class="service-price">${p?`от ${money(p.value)}`:'По прайсу'}${s.booking?`<button data-plan="${s.id}" data-service="${k}" aria-label="Добавить ${esc(services[k].name)} в план">${icon('plus')}</button>`:''}</div></div>`;}).join('')}<div class="notice">${s.price?'Приведены опубликованные позиции прайса. Цена зависит от категории мастера и состава услуги. ':''}${s.pending?'Меню требует прямого подтверждения.':'Сведения из открытого меню бренда; доступность конкретной процедуры уточняйте в филиале.'} Проверка источников: 15 ноября 2026.</div><a class="text-link" href="${esc(s.extraSource||s.source)}" target="_blank" rel="noopener noreferrer">Официальный источник ${icon('arrow-up')}</a>`;
 if(tab==='contacts')return `<div class="facts"><div class="fact"><span>АДРЕС</span><p>${esc(s.address)}</p></div><div class="fact"><span>КОНТАКТЫ</span><p>${s.phone?`<a href="tel:${s.phone}">${esc(s.phone)}</a>`:'Прямые контакты уточняются'}</p></div><div class="fact"><span>ВРЕМЯ РАБОТЫ</span><p>${esc(s.hours||'Уточняется при записи на сайте салона')}</p></div><div class="fact"><span>ЗАПИСЬ</span><p>${s.booking?'На официальном сайте салона':'Пока недоступна через карточку'}</p></div></div><div class="dialog-actions"><a class="button dark" href="https://yandex.ru/maps/?text=${encodeURIComponent(s.brand+' '+s.address.replace(' — требует прямого подтверждения',''))}" target="_blank" rel="noopener noreferrer">Открыть на карте ${icon('arrow-up')}</a>${s.phone?`<a class="button outline" href="tel:${s.phone}">Позвонить в салон</a>`:''}</div>`;
 return `<p>${esc(s.description)}</p><div class="facts"><div class="fact"><span>НАПРАВЛЕНИЯ</span><p>${s.categories.filter(c=>c!=='parallel').map(categoryName).map(esc).join(' · ')}</p></div><div class="fact"><span>ПАРАЛЛЕЛЬНЫЙ ФОРМАТ</span><p>${s.parallel?'Заявлен брендом. Сочетание и время подтверждает филиал.':'Возможность выполнения в несколько рук требует подтверждения.'}</p></div></div><div class="notice"><b>Статус Ultima: ${s.pending?'сверка сведений о филиале':'кандидат на независимую проверку'}.</b><br>Знак Ultima Selected ещё не присвоен. Наличие в стартовой коллекции не означает пройденный аудит или заключённое партнёрство.</div><a class="text-link" href="${esc(s.source)}" target="_blank" rel="noopener noreferrer">Сайт и меню бренда ${icon('arrow-up')}</a>`;}
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
let draft=null;
function startPlan(id=null,selected=[]){if(!account){showAccount();return;}draft={salon:id||salons.find(s=>s.booking).id,services:selected,date:'',time:'',silent:false,private:false,notes:''};planStageOne();}
function planStageOne(){const s=salons.find(s=>s.id===draft.salon);open(`<form class="plan-form" id="plan-services"><div class="eyebrow">ПЛАН ВИЗИТА</div><h2 id="dialog-title">Салон и услуги</h2><p>Соберите услуги в один визит. Актуальное время, мастера и стоимость вы подтвердите на сайте салона.</p><div class="plan-steps"><span class="active">01 / МЕСТО И УСЛУГИ</span><span>02 / ПОЖЕЛАНИЯ</span><span>03 / ВАШ ПЛАН</span></div><label class="field"><span>ВЫБЕРИТЕ САЛОН</span><select id="plan-salon">${salons.filter(s=>s.booking).map(s=>`<option value="${s.id}" ${s.id===draft.salon?'selected':''}>${esc(s.brand+' · '+s.branch)}</option>`).join('')}</select></label><div class="field-label">ЧТО ВКЛЮЧИТЬ В ВИЗИТ</div><div>${s.services.map(k=>`<label class="service-check"><input type="checkbox" name="service" value="${k}" ${draft.services.includes(k)?'checked':''}><span class="service-check-name">${esc(services[k].name)}${s.prices?.[k]?`<small>${esc(s.prices[k].note)}</small>`:''}</span><span>${s.prices?.[k]?`от ${money(s.prices[k].value)}`:'По прайсу'}</span></label>`).join('')}</div><div class="form-error" id="plan-error" role="alert"></div><div class="form-foot"><span>Подбор и планирование — бесплатно.</span><button class="button dark" type="submit">Продолжить ${icon('arrow')}</button></div></form>`);$('#plan-salon').addEventListener('change',e=>{const kept=$$('input[name=service]:checked',dialog).map(e=>e.value);draft.salon=e.target.value;const next=salons.find(s=>s.id===draft.salon);draft.services=kept.filter(k=>next.services.includes(k));planStageOne();});$('#plan-services').addEventListener('submit',e=>{e.preventDefault();draft.services=$$('input[name=service]:checked',dialog).map(e=>e.value);if(!draft.services.length){$('#plan-error').textContent='Выберите хотя бы одну услугу.';return;}planStageTwo();});}
function planStageTwo(){open(`<form class="plan-form" id="plan-preferences"><div class="eyebrow">ПЛАН ВИЗИТА</div><h2 id="dialog-title">Дата и пожелания</h2><p>Это желаемое время, а не свободный слот. Окончательное подтверждение даст салон.</p><div class="plan-steps"><span>01 / МЕСТО И УСЛУГИ</span><span class="active">02 / ПОЖЕЛАНИЯ</span><span>03 / ВАШ ПЛАН</span></div><div class="two-fields"><label class="field"><span>Дата</span><input id="plan-date" type="date" min="${today()}" value="${esc(draft.date)}" required></label><label class="field"><span>Время · МСК</span><input id="plan-time" type="time" value="${esc(draft.time)}" required></label></div><div class="field-label">ЧТО СДЕЛАЕТ ВИЗИТ КОМФОРТНЕЕ</div><div class="preference-row"><label class="preference"><input type="checkbox" id="plan-silent" ${draft.silent?'checked':''}>Silent Service</label><label class="preference"><input type="checkbox" id="plan-private" ${draft.private?'checked':''}>Приватный кабинет</label></div><label class="field"><span>ВАЖНЫЕ ПОЖЕЛАНИЯ · НЕОБЯЗАТЕЛЬНО</span><textarea id="plan-notes" maxlength="300" placeholder="Например: успеть до встречи, специалист по блонду, работать с ноутбуком">${esc(draft.notes)}</textarea></label><div class="notice">Параллельное выполнение услуг, Silent Service и кабинет — пожелания. Их наличие и возможную доплату подтверждает салон. Личные контакты здесь не нужны.</div><div class="form-error" id="plan-error" role="alert"></div><div class="form-foot"><button type="button" class="text-button" data-plan-back>← Место и услуги</button><button class="button dark" type="submit">Сохранить план ${icon('check')}</button></div></form>`);$('#plan-preferences').addEventListener('submit',async e=>{e.preventDefault();draft.date=$('#plan-date').value;draft.time=$('#plan-time').value;draft.silent=$('#plan-silent').checked;draft.private=$('#plan-private').checked;draft.notes=$('#plan-notes').value.trim();if(draft.date<today()){$('#plan-error').textContent='Выберите сегодняшнюю или будущую дату.';return;}await formAction(e.target,async()=>{const result=await api('visits','POST',{...draft,status:'planned'});await loadAccount();const plan=plans.find(p=>p.id===result.id);planSuccess(plan);});});}
function dateLabel(p){try{return new Date(p.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})+' · '+p.time+' МСК';}catch{return p.date+' '+p.time;}}
function planText(p){const s=salons.find(s=>s.id===p.salon);return `План визита · Ultima\n${s.brand} · ${s.branch}\n${s.address}\nЖелаемое время: ${dateLabel(p)}\nУслуги: ${p.services.map(k=>services[k]?.name).filter(Boolean).join(', ')}${p.silent?'\nПожелание: Silent Service':''}${p.private?'\nПожелание: приватный кабинет':''}${p.notes?'\nКомментарий: '+p.notes:''}\n\nЭто план, а не подтверждённая запись. Согласуйте время, услуги и цену с салоном.\n${s.booking}`;}
function planSuccess(p){const s=salons.find(s=>s.id===p.salon);open(`<div class="plan-form"><div class="success-symbol">U</div><div class="eyebrow">ПЛАН СОХРАНЁН</div><h2 id="dialog-title">Подтверждение в салоне</h2><p>Теперь подтвердите запись на официальном сайте салона. Удобно сначала скопировать услуги и пожелания.</p><div class="summary-box"><h3>${esc(s.brand)} · ${esc(s.branch)}</h3><p>${esc(dateLabel(p))}\n${esc(p.services.map(k=>services[k]?.name).filter(Boolean).join(' + '))}${p.silent?'\nSilent Service':''}${p.private?'\nПриватный кабинет':''}</p></div><div class="notice">Бронь пока не создана. План сохранён в вашем аккаунте Ultima. Время и финальная цена требуют подтверждения салона.</div><div class="dialog-actions"><a class="button dark" href="${esc(s.booking)}" target="_blank" rel="noopener noreferrer">Перейти к записи салона ${icon('arrow-up')}</a><button class="button outline" data-copy-plan="${p.id}">Скопировать план</button></div><div class="small-actions" style="margin-top:18px"><button data-calendar="${p.id}">Напомнить в календаре</button><button data-action="open-plans">Мои визиты</button></div></div>`);}
function showPlans(){showAccount('planned');}
async function copyPlan(id){const p=plans.find(p=>p.id===id);if(!p)return;try{await navigator.clipboard.writeText(planText(p));toast('План скопирован. Его можно передать салону.');}catch{open(`<div class="info-page"><h2 id="dialog-title">Ваш план</h2><p>Выделите текст ниже и скопируйте его.</p><label class="field"><span>ТЕКСТ ДЛЯ САЛОНА</span><textarea readonly style="min-height:300px">${esc(planText(p))}</textarea></label></div>`);}}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function calendar(id){const p=plans.find(p=>p.id===id);if(!p)return;const s=salons.find(s=>s.id===p.salon);const sanitize=v=>String(v).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const start=p.date.replace(/-/g,'')+'T'+p.time.replace(':','')+'00';const stamp=new Date().toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Ultima//Personal Plan//RU','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+p.id+'@ultima','DTSTAMP:'+stamp,'DTSTART;TZID=Europe/Moscow:'+start,'DURATION:PT15M','STATUS:TENTATIVE','SUMMARY:'+sanitize('Напоминание: согласовать визит в '+s.brand),'LOCATION:'+sanitize(s.address),'DESCRIPTION:'+sanitize(planText(p)),'END:VEVENT','END:VCALENDAR'].join('\r\n');download('ultima-visit-reminder.ics',text,'text/calendar;charset=utf-8');toast('Напоминание скачано. Это не подтверждение записи.');}
function showQuiz(){open(`<div class="info-page"><div class="eyebrow">ПОДБОР</div><h2 id="dialog-title">Задача визита</h2><p>Выберите ситуацию — мы сузим коллекцию до подходящего направления.</p><div class="quiz-options"><button class="quiz-choice" data-scenario="urgent"><span>Волосы</span><small>Срочная замена, окрашивание или укладка.</small></button><button class="quiz-choice" data-scenario="parallel"><span>Параллельные услуги</span><small>Несколько процедур за один визит.</small></button><button class="quiz-choice" data-scenario="move"><span>Поиск по району</span><small>Новый район и новые бьюти-привычки.</small></button><button class="quiz-choice" data-scenario="reset"><span>SPA и уход</span><small>SPA, восстановление и время для себя.</small></button></div></div>`);}
function quizDistrict(scenario){open(`<form class="info-page" id="quiz-location"><div class="eyebrow">ПОДБОР</div><h2 id="dialog-title">Район</h2><p>Учитываем выбранную задачу. Доступность мастеров и время подтвердит салон.</p><label class="field" style="margin-top:25px"><span>РАЙОН ИЛИ ЛОКАЦИЯ</span><select id="quiz-district"><option value="all">Вся коллекция</option>${districts.map(d=>`<option>${esc(d)}</option>`).join('')}</select></label><button class="button dark" type="submit">Показать подходящие места ${icon('arrow')}</button></form>`);$('#quiz-location').addEventListener('submit',e=>{e.preventDefault();reset();state.category=({urgent:'hair',parallel:'parallel',move:'all',reset:'spa'})[scenario];state.district=$('#quiz-district').value;render();close();$('#collection').scrollIntoView({behavior:'smooth'});toast('Коллекция подобрана по вашей задаче и району.');});}
function ritual(type){const selection=type==='nails'?['manicure','pedicure']:type==='full'?['styling','manicure','pedicure']:['styling','makeup'];const s=salons.find(s=>s.parallel&&selection.every(k=>s.services.includes(k)));startPlan(s?.id,selection);}
const info={
 method:`<div class="eyebrow">НЕЗАВИСИМЫЙ СТАНДАРТ</div><h2 id="dialog-title">Что означает <em>Ultima Selected.</em></h2><p>Это знак допуска конкретного филиала после проверки. Известность сети и рекламный бюджет его не заменяют. Сейчас все карточки представлены как кандидаты: проведённый аудит им не приписывается.</p><h3>Пять обязательных условий</h3><ul><li>География и пространство, соответствующие формату проекта.</li><li>Профильный уровень услуг и прозрачный прайс.</li><li>Не менее 70% косметических протоколов на утверждённых профессиональных линиях.</li><li>Санитарные требования и сервисный стандарт с подтверждениями.</li><li>Возможность надёжно подтвердить запись и согласовать условия работы.</li></ul><h3>Оценка по делу</h3><p>Базовый балл R складывается из мастерства (35%), безопасности (20%), пунктуальности, коммуникации и атмосферы (по 15%). Инфраструктура учитывается отдельно. Для первичного пилота предусмотрены очный аудит выше 90 баллов и R выше 85 при отсутствии критических нарушений.</p><h3>Допуск нужно поддерживать</h3><p>Плановая повторная проверка — не реже раза в полгода. При R ниже 80 филиал скрывается. Оплата продвижения не меняет результат проверки. Партнёрское размещение маркируется отдельно.</p>`,
 privacy:`<div class="eyebrow">КОНФИДЕНЦИАЛЬНОСТЬ</div><h2 id="dialog-title">Ваши данные</h2><p>В этой версии GitHub Pages профиль, избранное, планы, посещения и отзывы сохраняются в локальном хранилище браузера. Они не отправляются в базу Ultima, салонам или другим посетителям.</p><h3>Управление данными</h3><p>В профиле можно изменить имя, удалить посещение, оценку или весь демопрофиль. Очистка данных браузера также удалит сохранённое. На другом устройстве будет отдельный профиль.</p><button class="button outline" data-action="open-account">Открыть профиль</button>`,
 partners:`<div class="eyebrow">ДЛЯ САЛОНОВ И УПРАВЛЯЮЩИХ</div><h2 id="dialog-title">Для салонов</h2><p>Мы рассматриваем конкретные адреса, а не предоставляем общий допуск всей сети. Проверяются команда, косметика, санитарные протоколы и организация визита.</p><h3>Партнёрская модель</h3><p>Для клиента сервис бесплатный. Проектная комиссия салона — 15–20% только с первого состоявшегося визита нового привлечённого клиента: минимум 2 500 ₽, максимум 6 000 ₽. Товары с витрины и последующие визиты в базу комиссии не входят.</p><p>Новый клиент определяется по согласованной базе за предыдущие 365 дней. Сверка ежемесячная, оплата — до десятого числа следующего месяца. Условия и область базы закрепляются в договоре до подключения.</p><h3>Что подготовить</h3><ul><li>Адрес филиала, контакты управляющего и актуальное меню.</li><li>Список косметических линий и рабочие протоколы.</li><li>Данные о команде и подтверждения санитарных стандартов.</li><li>Сведения о CRM, кабинетах и параллельных услугах.</li></ul><p>Покупка допуска невозможна. Подача сведений не означает включение. Контакт для приёма заявок будет опубликован после назначения оператора сервиса.</p><button class="button outline" data-download-checklist>Скачать список для подготовки ${icon('download')}</button>`,
 launch:`<div class="eyebrow">GITHUB PAGES</div><h2 id="dialog-title">Версия для просмотра</h2><p>Каталог из 22 адресов, поиск, фильтры, избранное, планы, посещения и оценки. Демопрофиль сохраняется только в этом браузере. Общая серверная база и авторизация в этой копии не подключены.</p><p>У 18 адресов есть ссылка на официальный сайт для записи. Сохранённый план не является бронью. Четыре карточки требуют прямой сверки.</p>`
};
function showInfo(name){if(name==='sources'){open(`<div class="info-page"><div class="eyebrow">КАТАЛОГ / ИСТОЧНИКИ</div><h2 id="dialog-title">Источники сведений</h2><p>В основе — стартовый реестр проекта Ultima. Адреса и направления сверены по открытым страницам брендов 15 ноября 2026 года. Цены показаны только для отдельных опубликованных позиций, а не как средний чек салона.</p><div class="source-list">${window.ULTIMA_SOURCES.map(([n,u])=>`<div class="source-row"><span>${esc(n)}</span><a href="${u}" target="_blank" rel="noopener noreferrer">${esc(new URL(u).hostname)} ↗</a></div>`).join('')}</div><h3>Фотографии</h3><p>Изображения — с официальных сайтов BURO.Beauty, KYNSI, authentica club, MAHASH, Aldo Coppola и Domenico Castello. Для KEEP LOOKING используется фотография бренда. Конкретный источник и подпись указаны в карточке. Изображение бренда может иллюстрировать другой филиал; оно не подтверждает наличие показанного интерьера по каждому адресу.</p><h3>Карточки, требующие уточнения</h3><p>SLOWMO — два адреса из исходного проекта, прямой источник недоступен. DESSANGE — два адреса из реестра партнёров Guinot, прямое подтверждение ещё требуется. У этих четырёх карточек нет кнопки записи.</p><p>Ни одному филиалу пока не присвоен знак Ultima Selected.</p></div>`);}else open(`<div class="info-page">${info[name]||info.launch}</div>`);}
document.addEventListener('click',e=>{const t=e.target.closest('button,a,[data-open]');if(!t)return;
 if(t.dataset.nav){setNav(t.dataset.nav);if(t.dataset.nav==='favorites'){reset();state.favorites=true;render();$('#collection').scrollIntoView({behavior:'smooth'});return;}if(t.dataset.nav==='catalog')reset();}

 if(t.dataset.favorite){e.stopPropagation();favorite(t.dataset.favorite);return;}
 if(t.dataset.open){showSalon(t.dataset.open);return;}
 if(t.dataset.tab){showSalon(activeSalon,t.dataset.tab);return;}
 if(t.dataset.plan){startPlan(t.dataset.plan,t.dataset.service?[t.dataset.service]:[]);return;}
 if(t.hasAttribute('data-start-plan')){startPlan();return;}
 if(t.hasAttribute('data-plan-back')){draft.date=$('#plan-date').value;draft.time=$('#plan-time').value;draft.silent=$('#plan-silent').checked;draft.private=$('#plan-private').checked;draft.notes=$('#plan-notes').value;planStageOne();return;}
 if(t.dataset.action==='open-plans'){activeSalon=null;showPlans();return;}
 if(t.dataset.copyPlan){copyPlan(t.dataset.copyPlan);return;}
 if(t.dataset.calendar){calendar(t.dataset.calendar);return;}
 if(t.dataset.deletePlan){plans=plans.filter(p=>p.id!==t.dataset.deletePlan);persist('plans',plans);counts();showPlans();toast('План удалён. Это не отменяет запись в салоне.');return;}
 if(t.dataset.category){state.category=t.dataset.category;state.limit=6;render();return;}
 if(t.hasAttribute('data-reset')){reset();return;}
 if(t.dataset.clear){state[t.dataset.clear]=t.dataset.clear==='query'?'':'all';state.limit=6;render();return;}
 if(t.dataset.ritual){activeSalon=null;ritual(t.dataset.ritual);return;}
 if(t.dataset.scenario){quizDistrict(t.dataset.scenario);return;}
 if(t.dataset.info){activeSalon=null;showInfo(t.dataset.info);return;}
 if(t.hasAttribute('data-clear-data')){favorites.clear();plans=[];persist('favorites',[]);persist('plans',[]);render();$('#clear-data-status').textContent='Избранное и планы удалены с этого устройства.';return;}
 if(t.hasAttribute('data-download-checklist')){download('ultima-partner-checklist.txt','ULTIMA · Подготовка филиала к рассмотрению\n\n1. Адрес и контакты управляющего.\n2. Актуальный прайс и состав услуг.\n3. Список мастеров и их специализаций.\n4. Косметические линии и протоколы.\n5. Подтверждения санитарных стандартов.\n6. CRM и возможности записи.\n7. Параллельные услуги, ресурсы и кабинеты.\n8. Согласование договора и комиссии.\n\nПодача сведений не гарантирует допуск. Контакт оператора публикуется после назначения.','text/plain;charset=utf-8');}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.card-image[data-open]')){e.preventDefault();showSalon(e.target.dataset.open);}});
$('#search').addEventListener('input',e=>{state.query=e.target.value;state.limit=6;render();});$('#district').addEventListener('change',e=>{state.district=e.target.value;state.limit=6;render();});$('#sort').addEventListener('change',e=>{state.sort=e.target.value;render();});$('#favorites-filter').addEventListener('click',()=>{state.favorites=!state.favorites;state.limit=6;render();});$('#favorites-button').addEventListener('click',()=>{setNav('favorites');reset();state.favorites=true;render();$('#collection').scrollIntoView({behavior:'smooth'});});$('#load-more').addEventListener('click',()=>{state.limit+=6;render();});$('#concierge-button').addEventListener('click',()=>{activeSalon=null;showQuiz();});
// Shared Ultima account: server state is authoritative after sign-in.
let account=null,authReady=false,accountUnavailable=false,ratings={};
icons.user='<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>';
icons.star='<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3Z"/>';
icons.clock='<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>';
async function api(path,method='GET',body){if(window.ULTIMA_DEMO_API)return window.ULTIMA_DEMO_API(path,method,body);const response=await fetch('/api/'+path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json()}catch{throw new Error('Сервис временно недоступен. Попробуйте ещё раз.')}if(!response.ok){const error=new Error(data.error||'Не удалось выполнить запрос.');error.status=response.status;throw error;}return data;}
async function loadAccount(){try{account=await api('me');accountUnavailable=false;favorites=new Set(account.favorites);plans=account.visits;}catch(e){if(e.status!==401)accountUnavailable=true;account=null;}authReady=true;render();renderMembership();}
async function loadRatings(){try{const data=await api('ratings');ratings=Object.fromEntries(data.ratings.map(r=>[r.salon,r]));render();}catch{ratings={};}}
function ratingMarkup(s){const r=ratings[s.id];return `<span class="user-rating ${r?'has-rating':''}">${icon('star')}<span>${r?`${Number(r.average).toFixed(1).replace('.',',')} <small>· ${r.count} ${noun(r.count,['оценка','оценки','оценок'])}</small>`:'Нет оценок'}</span></span>`;}
function renderMembership(){const el=$('#membership-strip');if(!el)return;el.innerHTML=`<div class="membership-symbol">U</div><div class="membership-copy"><strong>${account?'Ваш профиль Ultima':'Единая программа Ultima'}</strong><span>${account?`${account.member.code} · Все салоны в одном профиле`:'Посещения, оценки и избранное во всех салонах'}</span></div>${account?`<div class="membership-stat"><b>${account.stats.visits}</b><span>${noun(account.stats.visits,['визит','визита','визитов'])}</span></div>`:''}<button class="membership-open" data-action="open-account">${account?'Мой профиль':'Открыть профиль'} ${icon('chevron')}</button>`;const text=$('#account-label');if(text)text.textContent=account?'Профиль':'Войти';}
function loginBlock(message='Единый профиль Ultima'){return `<div class="info-page account-login"><div class="account-glyph">${icon('user')}</div><div class="eyebrow">ULTIMA ACCOUNT</div><h2 id="dialog-title">${esc(message)}</h2><p>Демонстрационный профиль для всей коллекции. История посещений, оценки и избранное сохраняются в этом браузере.</p><div class="login-features"><span>${icon('calendar')}Общий счётчик посещений</span><span>${icon('star')}Оценки после визита</span><span>${icon('heart')}Личная коллекция салонов</span></div>${accountUnavailable?'<div class="notice">Не удалось загрузить профиль. Сохранённые данные останутся в аккаунте. Попробуйте ещё раз.</div><button class="button outline" data-account-retry>Повторить загрузку</button>':`<button class="button dark" data-demo-create>Создать демопрофиль ${icon('arrow')}</button><small class="account-note">Без регистрации. Данные остаются на этом устройстве.</small>`}</div>`;}
function showAccount(tab='history'){
 activeSalon=null;setNav('account');if(!authReady){open('<div class="info-page"><h2 id="dialog-title">Загрузка профиля</h2><p>Подключаем историю посещений…</p></div>');loadAccount().then(()=>showAccount(tab));return;}
 if(!account){open(loginBlock());return;}
 const st=account.stats;
 open(`<div class="account-page"><div class="account-heading"><div><span class="eyebrow">ЕДИНАЯ ПРОГРАММА</span><h2 id="dialog-title">Мой профиль</h2></div><div class="avatar">${esc(account.member.nickname.slice(0,1).toUpperCase())}</div></div><div class="member-card"><div class="member-card-top"><strong>ULTIMA</strong><span>MEMBER</span></div><div class="member-card-name">${esc(account.member.nickname)}</div><div class="member-card-bottom"><span>${esc(account.member.code)}</span><span>МОСКВА</span></div></div><div class="account-stats"><div><b>${st.visits}</b><span>Посещения</span></div><div><b>${st.salons}</b><span>Салоны</span></div><div><b>${st.reviews}</b><span>Оценки</span></div></div><p class="counter-note">Демопрофиль · данные только в этом браузере. Визиты внесены вами.</p><div class="account-tabs" role="tablist" aria-label="Разделы профиля">${[['history','Посещения'],['planned','Планы'+(st.planned?' · '+st.planned:'')],['profile','Настройки']].map(([id,label])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-account-tab="${id}">${label}</button>`).join('')}</div><div class="account-tab-content">${tab==='profile'?profileMarkup():historyMarkup(tab)}</div></div>`);
 if(tab==='profile')$('#profile-form').addEventListener('submit',async e=>{e.preventDefault();await formAction(e.target,async()=>{await api('me','PATCH',{nickname:$('#nickname').value});await loadAccount();showAccount('profile');toast('Имя профиля обновлено.');});});
}
function historyMarkup(tab){const list=account.visits.filter(v=>tab==='planned'?v.status==='planned':v.status!=='planned');return `<div class="history-heading"><h3>${tab==='planned'?'Планы визитов':'История посещений'}</h3><button class="text-link" ${tab==='planned'?'data-start-plan':'data-add-visit'}>${icon('plus')}${tab==='planned'?'Создать план':'Добавить'}</button></div>${list.length?`<div class="visit-list">${list.map(visitMarkup).join('')}</div>`:`<div class="history-empty"><span>${icon(tab==='planned'?'calendar':'clock')}</span><h3>${tab==='planned'?'Нет запланированных визитов':'Пока нет посещений'}</h3><p>${tab==='planned'?'Выберите салон и сохраните услуги и пожелания.':'Добавьте состоявшийся визит — он войдёт в общий счётчик Ultima.'}</p><button class="button dark" ${tab==='planned'?'data-start-plan':'data-add-visit'}>${tab==='planned'?'Выбрать салон':'Добавить посещение'} ${icon('plus')}</button></div>`}<p class="account-note">${tab==='planned'?'План не является бронью. Время и услуги подтверждает салон.':'Подтверждение салоном ещё не подключено. Отметка о визите основана на ваших данных.'}</p>`;}
function visitMarkup(v){const s=salons.find(s=>s.id===v.salon),completed=v.status==='completed';return `<article class="visit-row"><div class="visit-row-top"><span class="visit-status ${completed?'completed':''}">${completed?'Посещение':v.status==='cancelled'?'Отменено':'План'}</span><time>${esc(new Date(v.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'}))}${v.time?' · '+esc(v.time):''}</time></div><div class="visit-row-main">${s.image?`<img src="./assets/${s.image}.webp" alt="" loading="lazy">`:'<div class="visit-thumb">U</div>'}<div><button data-open="${s.id}" class="visit-salon">${esc(s.brand)}</button><span>${esc(s.branch)}</span><p>${esc(v.services.map(k=>services[k]?.name).filter(Boolean).join(' · '))}</p></div></div>${v.silent||v.private?`<p class="visit-note">${v.silent?'Silent Service':''}${v.silent&&v.private?' · ':''}${v.private?'Приватный кабинет':''}</p>`:''}${v.notes?`<p class="visit-note">${esc(v.notes)}</p>`:''}<div class="visit-actions">${completed?`<button data-review-visit="${v.id}" class="${v.review_rating?'rated':''}">${icon('star')}${v.review_rating?`${v.review_rating} · Изменить оценку`:'Оценить визит'}</button>`:v.status==='planned'?`${v.date<=today()?`<button data-visit-status="completed" data-visit-id="${v.id}">${icon('check')}Я посетил(а)</button>`:''}<button data-copy-plan="${v.id}">Скопировать план</button><button data-calendar="${v.id}">В календарь</button><button data-visit-status="cancelled" data-visit-id="${v.id}">Отменить план</button>${s.booking?`<a href="${esc(s.booking)}" target="_blank" rel="noopener noreferrer">Запись ↗</a>`:''}`:''}<button data-remove-visit="${v.id}" class="subtle-action">Удалить</button></div></article>`;}
function profileMarkup(){const localF=read('favorites',[]),localP=read('plans',[]);return `<form id="profile-form"><label class="field"><span>ИМЯ В ПРОФИЛЕ И ОТЗЫВАХ</span><input id="nickname" maxlength="40" required value="${esc(account.member.nickname)}" autocomplete="nickname"></label><p class="account-note">Имя используется в демонстрационных отзывах на этом устройстве.</p><div class="form-error" role="alert"></div><button class="button dark" type="submit">Сохранить ${icon('check')}</button></form><div class="settings-section"><h3>Данные с этого устройства</h3><p>Перенесите избранное и планы с этого устройства в демопрофиль.</p><button class="button outline" data-import-local ${!localF.length&&!localP.length?'disabled':''}>Перенести сохранённое</button><p id="import-result" class="account-note" role="status"></p></div><div class="settings-section"><h3>Аккаунт</h3><button class="danger-link" data-delete-account>Удалить данные Ultima</button><p class="account-note">Удалятся демопрофиль, история, избранное и отзывы из этого браузера.</p></div>`;}
async function formAction(form,action){const button=$('button[type=submit]',form),error=$('.form-error',form);if(button?.disabled)return;if(button)button.disabled=true;if(error)error.textContent='';try{await action();}catch(e){if(error)error.textContent=e.message;else toast(e.message);}finally{if(button)button.disabled=false;}}
function addVisit(salonId){if(!account){showAccount();return;}const selected=salons.find(s=>s.id===salonId)||salons[0];open(`<form class="info-page" id="visit-form"><div class="eyebrow">ИСТОРИЯ ULTIMA</div><h2 id="dialog-title">Добавить посещение</h2><p>Укажите состоявшийся визит. Он добавится в общий счётчик вашего профиля.</p><label class="field"><span>САЛОН</span><select id="visit-salon">${salons.map(s=>`<option value="${s.id}" ${s.id===selected.id?'selected':''}>${esc(s.brand+' · '+s.branch)}</option>`).join('')}</select></label><label class="field"><span>ДАТА ПОСЕЩЕНИЯ</span><input id="visit-date" type="date" min="2000-01-01" max="${today()}" value="${today()}" required></label><div class="field-label">УСЛУГИ</div><div id="visit-services"></div><p class="account-note">Визит будет отмечен как внесённый пользователем. Один визит в салон за день считается одним посещением.</p><div class="form-error" role="alert"></div><button class="button dark" type="submit">Добавить посещение ${icon('check')}</button></form>`);const draw=()=>{const s=salons.find(s=>s.id===$('#visit-salon').value);$('#visit-services').innerHTML=s.services.map(k=>`<label class="service-check"><input type="checkbox" name="visited-service" value="${k}"><span>${esc(services[k].name)}</span></label>`).join('')};draw();$('#visit-salon').addEventListener('change',draw);$('#visit-form').addEventListener('submit',e=>{e.preventDefault();formAction(e.target,async()=>{const selected=$$('input[name=visited-service]:checked',dialog).map(i=>i.value);if(!selected.length)throw new Error('Выберите хотя бы одну услугу.');const result=await api('visits','POST',{salon:$('#visit-salon').value,date:$('#visit-date').value,services:selected,status:'completed'});await loadAccount();toast('Посещение добавлено в общий счётчик.');showReview(result.id);});});}
function showReview(id){if(!account){showAccount();return;}const v=account.visits.find(v=>v.id===id);if(!v||v.status!=='completed')return;const s=salons.find(s=>s.id===v.salon);open(`<form class="info-page" id="review-form"><div class="eyebrow">ВАША ОЦЕНКА</div><h2 id="dialog-title">Как прошёл визит?</h2><p>${esc(s.brand)} · ${esc(s.branch)}<br>${esc(new Date(v.date+'T12:00:00').toLocaleDateString('ru-RU'))}</p><fieldset class="rating-input"><legend class="sr-only">Оценка от 1 до 5</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" ${v.review_rating===n?'checked':''} required><span aria-hidden="true">★</span><small>${n}</small><span class="sr-only">${n} из 5</span></label>`).join('')}</fieldset><label class="field"><span>КОММЕНТАРИЙ · НЕОБЯЗАТЕЛЬНО</span><textarea id="review-body" maxlength="2000" placeholder="Качество услуги, пунктуальность, сервис">${esc(v.review_body||'')}</textarea></label><div class="notice">В демонстрации оценка и отзыв сохранятся только в этом браузере под именем «${esc(account.member.nickname)}». Посещение внесено вами. Эта оценка не влияет на независимый допуск Ultima.</div><div class="form-error" role="alert"></div><button class="button dark" type="submit">${v.review_rating?'Обновить оценку':'Опубликовать оценку'} ${icon('arrow')}</button>${v.review_rating?`<button type="button" class="danger-link" data-delete-review="${id}">Удалить оценку</button>`:'<button type="button" class="text-button skip-review" data-action="open-account">Оценить позже</button>'}</form>`);$('#review-form').addEventListener('submit',e=>{e.preventDefault();formAction(e.target,async()=>{const rating=$('input[name=rating]:checked',dialog);if(!rating)throw new Error('Выберите оценку.');await api('reviews/'+id,'POST',{rating:Number(rating.value),body:$('#review-body').value});await Promise.all([loadAccount(),loadRatings()]);showAccount();toast('Спасибо. Демонстрационная оценка сохранена на этом устройстве.');});});}
async function showReviews(salonId,before=null){const s=salons.find(s=>s.id===salonId);if(!before)open(`<div class="info-page"><div class="eyebrow">ОЦЕНКИ КЛИЕНТОВ</div><h2 id="dialog-title">${esc(s.brand)}</h2><div id="salon-reviews"><p>Загружаем отзывы…</p></div></div>`);try{const data=await api('reviews?salon='+encodeURIComponent(salonId)+(before?'&before='+encodeURIComponent(before):''));const html=`${data.reviews.length?data.reviews.map(r=>`<article class="public-review"><div><strong>${esc(r.author)}</strong><span class="review-stars">${'★'.repeat(r.rating)}<span>${'★'.repeat(5-r.rating)}</span></span></div><time>${esc(new Date(r.created).toLocaleDateString('ru-RU'))}</time>${r.body?`<p>${esc(r.body)}</p>`:''}<small>Посещение внесено пользователем</small></article>`).join(''):'<div class="history-empty"><span>'+icon('star')+'</span><h3>Пока нет оценок</h3><p>Поделитесь впечатлением после посещения этого салона.</p></div>'}${data.next?`<button class="button outline" data-more-reviews="${salonId}" data-before="${esc(data.next)}">Ещё отзывы</button>`:''}`;if(before){$('[data-more-reviews]',dialog)?.remove();$('#salon-reviews').insertAdjacentHTML('beforeend',html);}else $('#salon-reviews').innerHTML=html+`<p class="account-note">Пользовательские оценки считаются отдельно от независимой проверки Ultima.</p><button class="button dark" data-add-visit="${salonId}">Добавить посещение и оценить ${icon('plus')}</button>`;}catch(e){if($('#salon-reviews'))$('#salon-reviews').textContent=e.message;}}
function confirmDelete(kind,id){const text=kind==='account'?'Все ваши данные Ultima будут удалены, включая опубликованные отзывы.':kind==='visit'?'Визит и связанная с ним оценка будут удалены из истории и общего счётчика.':'Оценка и текст отзыва будут удалены из карточки салона.';open(`<div class="info-page"><div class="eyebrow">УПРАВЛЕНИЕ ДАННЫМИ</div><h2 id="dialog-title">${kind==='account'?'Удалить данные Ultima?':kind==='visit'?'Удалить визит?':'Удалить оценку?'}</h2><p>${text}</p><div class="dialog-actions"><button class="button danger-button" data-confirm-delete="${kind}" data-delete-id="${id||''}">Удалить</button><button class="button outline" data-action="open-account">Оставить</button></div></div>`);}
async function importLocal(button){button.disabled=true;let saved=0,duplicates=0;try{for(const id of read('favorites',[])){if(salons.some(s=>s.id===id)){await api('favorites/'+id,'POST',{});saved++;}}for(const p of read('plans',[])){try{await api('visits','POST',{...p,status:'planned'});saved++;}catch(e){if(e.status===409){duplicates++;continue;}throw e;}}persist('favorites',[]);persist('plans',[]);await loadAccount();showAccount('profile');$('#import-result').textContent=`Перенесено записей: ${saved}. Уже были в профиле: ${duplicates}.`;}catch(e){toast(e.message);button.disabled=false;}}
document.addEventListener('click',async e=>{const t=e.target.closest('button,a');if(!t)return;try{
 if(t.hasAttribute('data-demo-create')){await window.ULTIMA_DEMO_CREATE();await loadAccount();showAccount();return;}
 if(t.dataset.action==='open-account'){showAccount();return;}
 if(t.dataset.accountTab){showAccount(t.dataset.accountTab);return;}
 if(t.hasAttribute('data-account-retry')){await loadAccount();showAccount();return;}
 if(t.hasAttribute('data-add-visit')){addVisit(t.dataset.addVisit);return;}
 if(t.dataset.reviewVisit){showReview(t.dataset.reviewVisit);return;}
 if(t.dataset.salonReviews){showReviews(t.dataset.salonReviews);return;}
 if(t.dataset.moreReviews){t.disabled=true;await showReviews(t.dataset.moreReviews,t.dataset.before);return;}
 if(t.dataset.visitStatus){t.disabled=true;await api('visits/'+t.dataset.visitId,'PATCH',{status:t.dataset.visitStatus});await loadAccount();if(t.dataset.visitStatus==='completed')showReview(t.dataset.visitId);else showAccount('planned');return;}
 if(t.hasAttribute('data-import-local')){await importLocal(t);return;}
 if(t.hasAttribute('data-delete-account')){confirmDelete('account');return;}
 if(t.dataset.removeVisit){confirmDelete('visit',t.dataset.removeVisit);return;}
 if(t.dataset.deleteReview){confirmDelete('review',t.dataset.deleteReview);return;}
 if(t.dataset.confirmDelete){t.disabled=true;const k=t.dataset.confirmDelete;await api(k==='account'?'me':(k==='visit'?'visits/':'reviews/')+t.dataset.deleteId,'DELETE');if(k==='account'){account=null;favorites=new Set();plans=[];persist('favorites',[]);persist('plans',[]);render();renderMembership();showAccount();}else{await loadAccount();showAccount();}await loadRatings();toast('Данные удалены.');}
 }catch(error){t.disabled=false;toast(error.message);}
});

function updateMobileFilters(){const count=Number(state.category!=='all')+Number(state.district!=='all')+Number(state.favorites)+Number(state.sort!=='editorial');const badge=$('#mobile-filter-count');badge.hidden=!count;badge.textContent=count;$('#mobile-filters').classList.toggle('has-filters',count>0);$('#mobile-filters').setAttribute('aria-label',count?'Открыть фильтры, выбрано: '+count:'Открыть фильтры');$('#search-clear').hidden=!state.query;}
function showMobileFilters(){
 activeSalon=null;const draft={category:state.category,district:state.district,sort:state.sort,favorites:state.favorites};
 const draw=()=>{open(`<form class="mobile-filter-form" id="mobile-filter-form"><div class="mobile-sheet-heading"><div><span class="eyebrow">КАТАЛОГ ULTIMA</span><h2 id="dialog-title">Фильтры</h2></div><button type="button" class="text-button" id="filter-reset">Сбросить</button></div><div class="mobile-filter-body"><label class="field"><span>Район</span><select id="filter-district"><option value="all">Все районы</option>${districts.map(d=>`<option value="${esc(d)}" ${draft.district===d?'selected':''}>${esc(d)}</option>`).join('')}</select></label><fieldset class="filter-directions"><legend>Направление</legend><div>${categories.map(c=>`<label class="filter-option"><input type="radio" name="filter-category" value="${c.id}" ${draft.category===c.id?'checked':''}><span>${icon(c.icon)}${esc(c.name)}</span></label>`).join('')}</div></fieldset><label class="field"><span>Сортировка</span><select id="filter-sort">${[['editorial','По списку'],['name','По названию'],['priced','Сначала с прайсом'],['rating','По оценкам клиентов']].map(([k,n])=>`<option value="${k}" ${draft.sort===k?'selected':''}>${n}</option>`).join('')}</select></label><label class="filter-favorite"><span>${icon('heart')}Только избранное</span><input type="checkbox" id="filter-favorites" role="switch" ${draft.favorites?'checked':''}></label></div><div class="mobile-filter-foot"><button type="submit" class="button dark" id="filter-apply">Показать ${filtered({...state,...draft}).length} ${noun(filtered({...state,...draft}).length,['адрес','адреса','адресов'])} ${icon('arrow')}</button></div></form>`);
 $('#mobile-filters').setAttribute('aria-expanded','true');
 const change=()=>{draft.category=$('input[name="filter-category"]:checked',dialog).value;draft.district=$('#filter-district').value;draft.sort=$('#filter-sort').value;draft.favorites=$('#filter-favorites').checked;const n=filtered({...state,...draft}).length;$('#filter-apply').innerHTML=`Показать ${n} ${noun(n,['адрес','адреса','адресов'])} ${icon('arrow')}`;};
 $('#mobile-filter-form').addEventListener('change',change);
 $('#filter-reset').addEventListener('click',()=>{Object.assign(draft,{category:'all',district:'all',sort:'editorial',favorites:false});draw();});
 $('#mobile-filter-form').addEventListener('submit',e=>{e.preventDefault();Object.assign(state,draft,{limit:6});render();close();$('#collection').scrollIntoView({behavior:'smooth'});});
 };draw();
}
$('#mobile-filters').addEventListener('click',showMobileFilters);
$('#search-clear').addEventListener('click',e=>{e.preventDefault();state.query='';state.limit=6;render();$('#search').focus();});
// Let the screen keyboard close naturally after a search rather than covering results.
$('#search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();e.target.blur();}});
// A single native Back step closes sheets; deeper transitions stay inside the same sheet.
let mobileSheetPushed=false;
const mobileView=()=>window.matchMedia('(max-width:760px)').matches;
const nativeShowModal=dialog.showModal.bind(dialog);
dialog.showModal=()=>{if(mobileView()&&!mobileSheetPushed){const sheetURL=location.href;history.replaceState(null,'',location.pathname+location.search+'#collection');history.pushState({ultimaSheet:true},'',sheetURL);mobileSheetPushed=true;}nativeShowModal();};
window.addEventListener('popstate',()=>{if(mobileSheetPushed){mobileSheetPushed=false;if(dialog.open)dialog.close();}});
dialog.addEventListener('close',()=>{if(mobileSheetPushed){mobileSheetPushed=false;history.back();}});
const updateViewport=()=>{const viewport=window.visualViewport;if(!viewport)return;document.documentElement.style.setProperty('--visible-height',viewport.height+'px');const keyboard=viewport.scale===1?Math.max(0,window.innerHeight-viewport.height-viewport.offsetTop):0;document.documentElement.style.setProperty('--keyboard-inset',keyboard+'px');};
window.addEventListener('resize',updateViewport);window.visualViewport?.addEventListener('resize',updateViewport);window.visualViewport?.addEventListener('scroll',updateViewport);updateViewport();

const districts=[...new Set(salons.map(s=>s.district))].sort((a,b)=>a.localeCompare(b,'ru'));
districts.forEach(d=>$('#district').insertAdjacentHTML('beforeend',`<option>${esc(d)}</option>`));
$('#categories').innerHTML=categories.map(c=>`<button class="category ${c.id==='all'?'active':''}" data-category="${c.id}" aria-pressed="${c.id==='all'}">${icon(c.icon)}${esc(c.name)}</button>`).join('');
$('#year').textContent=new Date().getFullYear();hydrate();render();renderMembership();loadAccount().then(()=>{if(location.hash==='#account')showAccount();});loadRatings();
if(location.hash.startsWith('#salon/'))showSalon(location.hash.slice(7));
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#salon/'))showSalon(location.hash.slice(7));if(location.hash==='#account')showAccount();});
})();
